package com.ecotrack.backend.gamification;
import com.ecotrack.backend.activity.ActivityRepository; import com.ecotrack.backend.analytics.AnalyticsService; import com.ecotrack.backend.user.UserRepository; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/gamification") public class GamificationController{private final GamificationRepository badges;private final UserBadgeRepository ub;private final UserRepository users;private final ActivityRepository acts;private final AnalyticsService analytics;public GamificationController(GamificationRepository b,UserBadgeRepository u,UserRepository users,ActivityRepository a,AnalyticsService x){badges=b;ub=u;this.users=users;acts=a;analytics=x;}private Long uid(){return users.findByEmailIgnoreCase(SecurityContextHolder.getContext().getAuthentication().getName()).orElseThrow().getId();}
 @GetMapping("/badges") public List<Badge> badges(){return badges.findAll();}
 @GetMapping("/badges/my") public List<UserBadge> my(){return ub.findByUserId(uid());}
 @PostMapping("/check") public Map<String,Object> check(){Long id=uid();return Map.of("activityCount",acts.countByUserId(id),"transportationCount",acts.countByUserIdAndCategory(id,"TRANSPORTATION"),"score",analytics.score(id),"message","Badge criteria can be evaluated here; award logic can be extended as the project grows.");}
 @GetMapping("/leaderboard") public List<Map<String,Object>> leaderboard(){return users.findAll().stream().map(u->{Map<String,Object> row=new HashMap<>();row.put("userId",u.getId());row.put("name",u.getName());row.put("score",analytics.score(u.getId()));return row;}).sorted((a,b)->Double.compare(((Number)b.get("score")).doubleValue(),((Number)a.get("score")).doubleValue())).toList();}
}
